fn inzzLisz(list: []const []const u8, text: []const u8) bool { for (list) |item| { if (std.ascii.eqlIgnoreCase(item, text)) return true; } return false; }
fn firsLowz(text: []const u8, patn: []const u8) bool { return text.len >= patn.len and std.ascii.eqlIgnoreCase(text[0..patn.len], patn); }
pub const Spli = struct { labl: []const u8, rest: []const u8 };
pub fn lablSpli(line: []const u8) Spli { const colz = std.mem.indexOfScalar(u8, line, ':') orelse return .{ .labl = std.mem.trim(u8, line, " "), .rest = "" }; if (colz > 40) return .{ .labl = std.mem.trim(u8, line, " "), .rest = "" }; return .{ .labl = std.mem.trim(u8, line[0..colz], " "), .rest = std.mem.trim(u8, line[colz + 1 ..], " ") }; }
pub fn labeFind(labl: []const u8) Fidz { var buff: [64]u8 = undefined; var look = labl; if (labl.len >= 2 and labl.len <= buff.len and labl[0] == 0xC4 and labl[1] == 0x90) { @memcpy(buff[0..labl.len], labl); buff[1] = 0x91; look = buff[0..labl.len]; } for (ROWS) |rowz| { if (std.ascii.eqlIgnoreCase(rowz.labl, look)) return rowz.fidz; } return .none; }
pub fn junkValz(valu: []const u8) bool { const junk = [_][]const u8{ "-", "--", "n/a", "no data", "đang cập nhật", "chưa cập nhật", "phiên bản khác", "khác" }; var buff: [64]u8 = undefined; var look = valu; if (valu.len >= 2 and valu.len <= buff.len and valu[0] == 0xC4 and valu[1] == 0x90) { @memcpy(buff[0..valu.len], valu); buff[1] = 0x91; look = buff[0..valu.len]; } for (junk) |item| { if (std.ascii.eqlIgnoreCase(item, look)) return true; } return false; }
pub fn iszzDesc(line: []const u8) bool { return inzzLisz(&DESC, std.mem.trim(u8, line, " :")); }
pub fn iszzStop(line: []const u8) bool { for (STOP) |patn| { if (firsLowz(line, patn)) return true; } return false; }
pub fn iszzDead(line: []const u8) bool { for (DEAD) |patn| { if (firsLowz(line, patn)) return true; } return false; }
pub fn iszzSimi(line: []const u8) bool { return firsLowz(line, "xe tương tự") or firsLowz(line, "tin tương tự") or firsLowz(line, "tin đăng khác"); }
